import os
import torch
import random
import numpy as np


class Config:
    # ==========================================
    # System Settings
    # ==========================================
    SEED = 42
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    # Using 8 workers to leave some CPU headroom for the main process
    NUM_WORKERS = 8

    # ==========================================
    # File Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for checkpoints and cached data
    WORKING_DIR = "./working/idea_2"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Submission directory
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Model Checkpoint Path
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    MODEL_NAME = "efficientnet_b0"
    NUM_CLASSES = 32093
    PRETRAINED = True

    # Input dimensions
    IMG_SIZE = 224
    CHANNELS = 3

    # ImageNet Normalization Stats
    MEAN = [0.485, 0.456, 0.406]
    STD = [0.229, 0.224, 0.225]

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    # A100 40GB can handle larger batches for B0, but 128 is safe and efficient
    BATCH_SIZE = 128
    NUM_EPOCHS = 8
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4

    # Optimization
    PATIENCE = 3  # Early stopping patience

    # Focal Loss Parameters
    FOCAL_GAMMA = 2.0
    FOCAL_ALPHA = 0.25

    # ==========================================
    # Debugging / Development
    # ==========================================
    # Set DEBUG to True to run on a small subset of data
    DEBUG = False
    DEBUG_SUBSET_SIZE = 5000

    @classmethod
    def set_seed(cls):
        """
        Sets the random seed for reproducibility across Python, NumPy, and PyTorch.
        """
        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed(cls.SEED)
            torch.cuda.manual_seed_all(cls.SEED)
            # Ensure deterministic behavior
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
